    name: string;
}

interface NoteEditorFormProps {
    action: (prevState: NoteFormState, formData: FormData) => Promise<NoteFormState>;
    defaultTitle: string;
    defaultBody: string;
    defaultChannelId: string;
    defaultIsPublished: boolean;
    channels: ChannelOption[];
