    action,
    defaultTitle,
    defaultBody,
    defaultChannelId,
    defaultIsPublished,
    channels,
    backHref,
    labels,
}: NoteEditorFormProps) {
    const [state, formAction, isPending] = useActionState<NoteFormState, FormData>(action, { error: null });

    return (
        <form action={formAction} className="space-y-6">
