                <label htmlFor="isPublished" className="text-sm font-medium text-gray-700">
                    {labels.publishToChannel}
                </label>
            </div>
            {state.error && <p className="text-sm text-red-600">{state.error}</p>}
            <div className="flex gap-3">
                <button
